package cl.acis.catalogos.model; import jakarta.persistence.*;
@Entity @Table(name="equipos") public class Equipo { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false) Long clienteId; @Column(nullable=false) String tipo,marca,modelo,serie,ubicacion; @Column(nullable=false) boolean exterior; @Column(nullable=false) boolean activo=true; public Equipo(){} public Long getId(){return id;} public Long getClienteId(){return clienteId;} public void setClienteId(Long v){clienteId=v;} public String getTipo(){return tipo;} public void setTipo(String v){tipo=v;} public String getMarca(){return marca;} public void setMarca(String v){marca=v;} public String getModelo(){return modelo;} public void setModelo(String v){modelo=v;} public String getSerie(){return serie;} public void setSerie(String v){serie=v;} public String getUbicacion(){return ubicacion;} public void setUbicacion(String v){ubicacion=v;} public boolean isExterior(){return exterior;} public void setExterior(boolean v){exterior=v;} public boolean isActivo(){return activo;} public void setActivo(boolean v){activo=v;} }
